import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useResponsiveStepperOrientation } from '../../hooks/useResponsiveStepperOrientation';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Step,
  StepLabel,
  Stepper,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { GHG_BOUNDARY_PROFILE_PATH, GHG_BOUNDARY_OPERATIONS_PATH } from '../../constants/ghgBoundaryRoutes';
import ApiService from '../../services/api';
import { reportingTabHref } from '../../constants/reportingTabs';
import { DOCUMENT_UPLOAD_PATH } from '../../constants/documentRoutes';
import OrchestrationRunPanel, { type OrchestrationRunSummary, stagesFromRun } from './OrchestrationRunPanel';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { MODULE_CHECK_LABELS } from '../../constants/orchestrationUxLabels';

type PcfProduct = {
  productId?: string;
  productName: string;
  functionalUnit?: string;
  productionVolume?: number;
  productionVolumeUnit?: string;
  allocationMethod?: string;
};

type UnifiedProduct = {
  productName: string;
  combinedKgCo2e?: number;
  transactionKgCo2e?: number;
  workflowKgCo2e?: number;
  kgCo2ePerFunctionalUnit?: number;
  productionVolume?: number;
  functionalUnit?: string;
};

const PCF_MODES = [
  { value: 'quick', label: 'Quick estimate', description: 'Workflow-based footprint only — minimal setup' },
  { value: 'operational', label: 'Operational', description: 'Rules + AI auto-classify on transactions (recommended)' },
  { value: 'detailed', label: 'Detailed LCI', description: 'Full activity data path for audit preparation' },
];

const ALLOCATION_METHODS = [
  { value: 'economic_allocation', label: 'Economic (revenue / value)' },
  { value: 'physical_allocation', label: 'Physical (mass / volume)' },
  { value: 'energy_allocation', label: 'Energy-based' },
];

const WIZARD_STEPS = ['Products & mode', 'Functional units', 'Attribution rules', 'Review & run'];

const ProductPcfWorkspace: React.FC = () => {
  const { strings } = useReadinessLocale();
  const { orientation, alternativeLabel } = useResponsiveStepperOrientation();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [runningAi, setRunningAi] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [wizardStep, setWizardStep] = useState(0);
  const [setup, setSetup] = useState<Record<string, unknown> | null>(null);
  const [unified, setUnified] = useState<Record<string, unknown> | null>(null);
  const [exceptions, setExceptions] = useState<Record<string, unknown>[]>([]);
  const [lastPcfRun, setLastPcfRun] = useState<OrchestrationRunSummary | null>(null);
  const [pcfStages, setPcfStages] = useState<Array<{ stage: string; status: string; durationMs?: number | null }>>([]);
  const [pcfAnalysisSummary, setPcfAnalysisSummary] = useState<Record<string, unknown> | null>(null);

  const [pcfMode, setPcfMode] = useState('operational');
  const [products, setProducts] = useState<PcfProduct[]>([]);
  const [functionalUnit, setFunctionalUnit] = useState('1 unit of product');
  const [allocationMethod, setAllocationMethod] = useState('economic_allocation');
  const [rulePattern, setRulePattern] = useState('');
  const [ruleProductName, setRuleProductName] = useState('');
  const [rules, setRules] = useState<Record<string, unknown>[]>([]);
  const [defaultSystemBoundary, setDefaultSystemBoundary] = useState('cradle-to-gate');

  const setupComplete = Boolean(setup?.setupComplete);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [setupRes, unifiedRes, exceptionsRes] = await Promise.all([
        ApiService.getProductPcfSetup(),
        ApiService.getUnifiedProductPcf().catch(() => null),
        ApiService.getProductPcfExceptions({ limit: 20 }).catch(() => null),
      ]);

      const setupData = (setupRes as { data?: Record<string, unknown> })?.data ?? setupRes;
      setSetup(setupData as Record<string, unknown>);
      setPcfMode(String(setupData?.pcfMode || 'operational'));
      setProducts(Array.isArray(setupData?.products) ? setupData.products as PcfProduct[] : []);
      const iso = (setupData?.iso14067 || {}) as Record<string, string>;
      setFunctionalUnit(iso.functionalUnit || '1 unit of product');
      setAllocationMethod(iso.allocationMethod || 'economic_allocation');
      setRules(Array.isArray(setupData?.rules) ? setupData.rules as Record<string, unknown>[] : []);
      const lcaSetup = (setupData?.lca || {}) as {
        defaultSystemBoundary?: string;
        ghgBoundaryContext?: { defaultProductSystemBoundary?: string };
      };
      setDefaultSystemBoundary(
        lcaSetup.defaultSystemBoundary
        || lcaSetup.ghgBoundaryContext?.defaultProductSystemBoundary
        || 'cradle-to-gate'
      );

      const agentOrch = (setupData?.agentOrchestration || {}) as {
        lastRuns?: Record<string, OrchestrationRunSummary>;
      };
      if (agentOrch.lastRuns?.product_pcf) {
        setLastPcfRun(agentOrch.lastRuns.product_pcf);
        setPcfStages(stagesFromRun(agentOrch.lastRuns.product_pcf));
      }

      if (unifiedRes) {
        const unifiedData = (unifiedRes as { data?: Record<string, unknown> })?.data ?? unifiedRes;
        setUnified(unifiedData as Record<string, unknown>);
      }

      const excData = (exceptionsRes as { data?: { transactions?: Record<string, unknown>[] } })?.data;
      const excTransactions = excData?.transactions;
      setExceptions(Array.isArray(excTransactions) ? excTransactions : []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load product PCF workspace');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const stats = (setup?.stats || {}) as Record<string, number>;
  const activeMode = PCF_MODES.find((mode) => mode.value === pcfMode) || PCF_MODES[1];
  const modeProfile = (unified?.modeProfile || setup?.modeProfile) as {
    label?: string;
    description?: string;
    supportsAutoClassify?: boolean;
    primarySource?: string;
  } | undefined;
  const lcaSummary = unified?.lca as {
    studyCount?: number;
    totalKgCo2e?: number;
    averageDataQualityScore?: number;
    framework?: string;
    defaultSystemBoundary?: string;
    impactCategoryCount?: number;
    ghgBoundaries?: {
      defaultProductSystemBoundary?: string;
      completeness?: {
        organizationalDocumented?: boolean;
        operationalDocumented?: boolean;
      };
      organizationalBoundary?: {
        consolidationApproachLabel?: string | null;
        consolidationApproach?: string | null;
      };
      operationalBoundary?: {
        scope3CategoriesIncluded?: number[];
      };
      inventoryFilter?: { filtered?: boolean; excludedCount?: number };
    };
  } | null | undefined;
  const setupLca = setup?.lca as {
    defaultSystemBoundary?: string;
    ghgBoundaryContext?: {
      defaultProductSystemBoundary?: string;
      completeness?: { organizationalDocumented?: boolean; operationalDocumented?: boolean };
    };
  } | undefined;
  const ghgBoundaries = lcaSummary?.ghgBoundaries;
  const boundariesReady = Boolean(
    ghgBoundaries?.completeness?.organizationalDocumented
    && ghgBoundaries?.completeness?.operationalDocumented
  );
  const lcaStudiesFromUnified = unified && Array.isArray(unified.lcaStudies)
    ? unified.lcaStudies
    : [];
  const firstStudyImpacts = (lcaStudiesFromUnified[0]
    ? (lcaStudiesFromUnified[0] as { impactAssessment?: { impacts?: Array<{ label?: string; value?: number; unit?: string }> } })
        .impactAssessment?.impacts
    : []) as Array<{ label?: string; value?: number; unit?: string }>;

  const handleDownloadLcaReport = async () => {
    setError(null);
    try {
      const res = await ApiService.getProductLcaReport();
      const payload = (res as { data?: unknown })?.data ?? res;
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = 'product-lca-disclosure-pack.json';
      anchor.click();
      URL.revokeObjectURL(url);
      setSuccess('LCA disclosure pack downloaded.');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to download LCA report');
    }
  };

  const lcaStudies = lcaStudiesFromUnified as Array<{
    productName?: string;
    totalKgCo2e?: number;
    dataQualityScore?: number;
    referenceFlow?: { totalKgCo2e?: number };
    interpretation?: {
      dataQualityScore?: number;
      hotspots?: Array<{ label?: string; sharePercent?: number }>;
    };
  }>;

  const detailedLci = unified?.detailedLci as {
    tier1AttributedCount?: number;
    tier1CoveragePct?: number;
    totalEmittingTransactions?: number;
    excludedSpendProxyCount?: number;
    excludedUnattributedCount?: number;
  } | null | undefined;
  const supportsAutoClassify = modeProfile?.supportsAutoClassify ?? pcfMode !== 'quick';
  const showWorkflowColumn = pcfMode !== 'detailed';
  const showTransactionColumn = pcfMode !== 'quick';

  const handleSaveSetup = async (markComplete = false) => {
    setSaving(true);
    setError(null);
    setSuccess(null);
    try {
      await ApiService.saveProductPcfSetup({
        pcfMode,
        products,
        rules,
        defaultSystemBoundary,
        iso14067: {
          functionalUnit,
          allocationMethod,
          systemBoundaryType: defaultSystemBoundary,
          enabled: true,
        },
        setupComplete: markComplete,
      });
      if (markComplete) {
        await ApiService.completeProductPcfSetup();
        setSuccess('Product PCF setup completed and synced to compliance hub.');
      } else {
        setSuccess('Product PCF setup saved.');
      }
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save setup');
    } finally {
      setSaving(false);
    }
  };

  const handleRunAiClassify = async (dryRun = false) => {
    setRunningAi(true);
    setError(null);
    setSuccess(null);
    try {
      const response = await ApiService.orchestrateProductPcf({
        dryRun,
        includeUnifiedView: true,
        useFullOrchestration: true,
      });
      const data = (response as { data?: Record<string, unknown> })?.data ?? response;
      setPcfStages((data?.stages as typeof pcfStages) || []);
      setPcfAnalysisSummary(
        (data?.pcfAnalysis as Record<string, unknown>)
        || ((data?.agentOutputs as Record<string, unknown>)?.product_pcf_analysis as { summary?: Record<string, unknown> } | undefined)?.summary
        || (data?.summary as Record<string, unknown>)
        || null
      );
      setLastPcfRun((data?.orchestrationRun as OrchestrationRunSummary) || {
        orchestratorType: 'product_pcf',
        scoreAfter: data?.overallReadinessScore as number,
        scoreDelta: data?.scoreDelta as number,
        message: data?.message as string,
        lastRunAt: new Date().toISOString(),
        success: data?.success !== false,
        stagesCompleted: Array.isArray(data?.stages)
          ? (data.stages as Array<{ status: string }>).filter((s) => s.status === 'completed').length
          : undefined
      });

      const classification = (data?.agentOutputs as Record<string, unknown>)?.product_attribution_advisor as Record<string, unknown>
        || (data?.classification as Record<string, unknown>)
        || data;
      const classifyPayload = (classification?.classification || classification) as Record<string, unknown>;
      const excCount = Array.isArray(classifyPayload?.exceptions)
        ? classifyPayload.exceptions.length
        : Array.isArray((data?.agentOutputs as Record<string, unknown>)?.gapSynthesis)
          ? 0
          : Number((data?.agentOutputs as { gapSynthesis?: { attributionExceptions?: number } })?.gapSynthesis?.attributionExceptions || 0);

      setSuccess(
        dryRun
          ? `PCF analysis preview: ${data?.overallReadinessScore != null ? `${Math.round(Number(data.overallReadinessScore))}% readiness` : 'complete'}${excCount ? ` · ${excCount} exceptions` : ''}`
          : String(
            data?.message
            || (data?.pcfAnalysis as { totalKgCo2e?: number; productCount?: number })?.totalKgCo2e
              ? `Calculated ${(data.pcfAnalysis as { productCount?: number }).productCount ?? 0} product footprint(s) — ${(data.pcfAnalysis as { totalKgCo2e?: number }).totalKgCo2e} kg CO₂e`
              : `Product PCF analysis complete${excCount ? ` · ${excCount} exceptions to review` : ''}`
          )
      );
      const unifiedView = (data?.unifiedView ?? classification?.unifiedView) as Record<string, unknown> | undefined;
      if (unifiedView && typeof unifiedView === 'object') {
        setUnified(unifiedView);
      }
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : strings.pcfOrchestrationFailed);
    } finally {
      setRunningAi(false);
    }
  };

  const handleAnalyzeFeedOnly = async (dryRun = false) => {
    setRunningAi(true);
    setError(null);
    setSuccess(null);
    try {
      const response = await ApiService.analyzeProductPcfFeed({
        dryRun,
        recalculateEmissions: true,
        runAttribution: true,
        persistResults: !dryRun,
      });
      const data = (response as { data?: Record<string, unknown> })?.data ?? response;
      setPcfStages((data?.stages as typeof pcfStages) || []);
      setPcfAnalysisSummary((data?.summary as Record<string, unknown>) || null);
      setLastPcfRun((data?.orchestrationRun as OrchestrationRunSummary) || {
        orchestratorType: 'product_pcf_analysis',
        scoreAfter: (data?.summary as { totalKgCo2e?: number })?.totalKgCo2e,
        message: data?.message as string,
        lastRunAt: new Date().toISOString(),
        success: data?.success !== false,
        stagesCompleted: Array.isArray(data?.stages)
          ? (data.stages as Array<{ status: string }>).filter((s) => s.status === 'completed').length
          : undefined,
      });
      setSuccess(String(data?.message || 'Product PCF feed analysis complete'));
      const unifiedView = data?.unifiedView as Record<string, unknown> | undefined;
      if (unifiedView && typeof unifiedView === 'object') {
        setUnified(unifiedView);
      }
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Product PCF feed analysis failed');
    } finally {
      setRunningAi(false);
    }
  };

  const addRule = () => {
    if (!rulePattern.trim() || !ruleProductName.trim()) return;
    setRules((prev) => [
      ...prev,
      {
        ruleId: `rule_${Date.now()}`,
        name: `${rulePattern} → ${ruleProductName}`,
        type: 'keyword',
        pattern: rulePattern.trim(),
        emissionBoundary: 'product',
        productNames: [ruleProductName.trim()],
        confidence: 0.9,
        enabled: true,
      },
    ]);
    setRulePattern('');
  };

  const unifiedProducts = useMemo(() => {
    const products = unified?.products;
    return Array.isArray(products) ? products as UnifiedProduct[] : [];
  }, [unified]);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" py={6}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Stack spacing={3}>
      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      <Alert severity="info">
        <strong>{modeProfile?.label || activeMode.label}:</strong>{' '}
        {modeProfile?.description || activeMode.description}
      </Alert>

      {pcfMode === 'detailed' && detailedLci && (
        <Alert severity={detailedLci.tier1CoveragePct && detailedLci.tier1CoveragePct >= 50 ? 'success' : 'warning'}>
          Detailed LCI uses Tier-1 attributed transactions only —{' '}
          {detailedLci.tier1AttributedCount ?? 0} of {detailedLci.totalEmittingTransactions ?? 0}{' '}
          emitting rows qualify ({detailedLci.tier1CoveragePct ?? 0}% coverage).
        </Alert>
      )}

      {pcfMode === 'quick' && (
        <Alert severity="warning">
          Quick estimate mode ignores transaction allocation. Complete the Manufacturing Workflow Planner
          for product-level estimates, or switch to Operational / Detailed LCI when books are ready.
        </Alert>
      )}

      {pcfAnalysisSummary ? (
        <Alert severity="success">
          <Typography variant="subtitle2" gutterBottom>Latest PCF calculation</Typography>
          <Typography variant="body2">
            {Number(pcfAnalysisSummary.productCount || 0)} product(s) ·{' '}
            {Number(pcfAnalysisSummary.totalKgCo2e || 0).toLocaleString()} kg CO₂e total
            {pcfAnalysisSummary.inventoryCoveragePercent != null
              ? ` · ${Number(pcfAnalysisSummary.inventoryCoveragePercent)}% inventory attributed`
              : ''}
            {Number(pcfAnalysisSummary.emissionsEnriched || 0) > 0
              ? ` · ${Number(pcfAnalysisSummary.emissionsEnriched)} transaction(s) enriched with emissions`
              : ''}
          </Typography>
        </Alert>
      ) : null}

      <Alert severity={boundariesReady ? 'success' : 'info'}>
        Product LCA reuses your{' '}
        <RouterLink to={GHG_BOUNDARY_PROFILE_PATH}>organizational boundary</RouterLink>
        {' '}(profile) and{' '}
        <RouterLink to={GHG_BOUNDARY_OPERATIONS_PATH}>operational boundary</RouterLink>
        {' '}(operations) for scope, grid factors, and lifecycle modules.
        {setupLca?.ghgBoundaryContext && !boundariesReady
          ? ' Complete both boundary forms for filtered inventory and automatic cradle-to-grave modules (Scope 3 cat. 11/12).'
          : null}
        {ghgBoundaries?.inventoryFilter?.filtered
          ? ` Operational boundary filter excluded ${ghgBoundaries.inventoryFilter.excludedCount ?? 0} transaction(s) from LCI.`
          : null}
      </Alert>

      {lcaSummary && (lcaSummary.studyCount ?? 0) > 0 ? (
        <Card variant="outlined">
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Integrated LCA (ISO 14040/14044 → ISO 14067 PCF)
            </Typography>
            {ghgBoundaries?.organizationalBoundary?.consolidationApproachLabel ? (
              <Typography variant="caption" color="text.secondary" display="block" gutterBottom>
                Org: {ghgBoundaries.organizationalBoundary.consolidationApproachLabel}
                {ghgBoundaries.operationalBoundary?.scope3CategoriesIncluded?.length
                  ? ` · Scope 3 cats: ${ghgBoundaries.operationalBoundary.scope3CategoriesIncluded.join(', ')}`
                  : ''}
              </Typography>
            ) : null}
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} mb={1}>
              <Typography variant="body2" color="text.secondary" sx={{ flex: 1 }}>
                {lcaSummary.framework || 'ISO 14040/14044'} ·{' '}
                {lcaSummary.studyCount} study/studies · {lcaSummary.impactCategoryCount ?? 7} impact categories · avg
                data quality {Math.round(Number(lcaSummary.averageDataQualityScore || 0))}%
              </Typography>
              <FormControl size="small" sx={{ minWidth: 180 }}>
                <InputLabel>System boundary</InputLabel>
                <Select
                  label="System boundary"
                  value={defaultSystemBoundary}
                  onChange={(e) => setDefaultSystemBoundary(String(e.target.value))}
                >
                  <MenuItem value="cradle-to-gate">Cradle-to-gate</MenuItem>
                  <MenuItem value="cradle-to-grave">Cradle-to-grave</MenuItem>
                </Select>
              </FormControl>
              <Typography variant="caption" color="text.secondary" sx={{ alignSelf: 'center' }}>
                Suggested: {ghgBoundaries?.defaultProductSystemBoundary
                  || setupLca?.ghgBoundaryContext?.defaultProductSystemBoundary
                  || 'cradle-to-gate'} from operations Scope 3
              </Typography>
              <Button size="small" variant="outlined" onClick={() => handleSaveSetup(false)} disabled={saving}>
                Save boundary
              </Button>
              <Button
                size="small"
                variant="text"
                disabled={saving}
                onClick={async () => {
                  setSaving(true);
                  setError(null);
                  try {
                    await ApiService.syncProductPcfFromGhgBoundaries(true);
                    setSuccess('Synced product PCF/LCA settings from profile & operations boundaries.');
                    await load();
                  } catch (err) {
                    setError(err instanceof Error ? err.message : 'Boundary sync failed');
                  } finally {
                    setSaving(false);
                  }
                }}
              >
                Sync from GHG boundaries
              </Button>
              <Button size="small" variant="contained" onClick={handleDownloadLcaReport}>
                Download LCA pack
              </Button>
            </Stack>
            {firstStudyImpacts.length > 0 ? (
              <Typography variant="caption" color="text.secondary" display="block" gutterBottom>
                Sample impacts (product 1):{' '}
                {firstStudyImpacts.slice(0, 4).map((impact) => (
                  `${impact.label}: ${Number(impact.value || 0).toFixed(2)} ${impact.unit || ''}`
                )).join(' · ')}
              </Typography>
            ) : null}
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Product</TableCell>
                  <TableCell align="right">kg CO₂e</TableCell>
                  <TableCell align="right">Data quality</TableCell>
                  <TableCell>Top hotspot</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {lcaStudies.slice(0, 8).map((study) => {
                  const hotspot = study.interpretation?.hotspots?.[0];
                  return (
                    <TableRow key={study.productName}>
                      <TableCell>{study.productName}</TableCell>
                      <TableCell align="right">
                        {Number(study.referenceFlow?.totalKgCo2e ?? study.totalKgCo2e ?? 0).toLocaleString()}
                      </TableCell>
                      <TableCell align="right">
                        {Math.round(Number(study.interpretation?.dataQualityScore ?? study.dataQualityScore ?? 0))}%
                      </TableCell>
                      <TableCell>
                        {hotspot
                          ? `${hotspot.label} (${hotspot.sharePercent ?? 0}%)`
                          : '—'}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      ) : null}

      <Grid container spacing={2}>
        <Grid item xs={12} md={3}>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="overline">Products</Typography>
              <Typography variant="h5">{stats.productCount ?? products.length}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="overline">Unclassified</Typography>
              <Typography variant="h5">{stats.unclassifiedCount ?? 0}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="overline">Low confidence</Typography>
              <Typography variant="h5">{stats.lowConfidenceCount ?? exceptions.length}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="overline">Setup</Typography>
              <Chip
                size="small"
                color={setupComplete ? 'success' : 'warning'}
                label={setupComplete ? 'Complete' : 'In progress'}
              />
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {!setupComplete && (
        <Card variant="outlined">
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Product PCF setup wizard
            </Typography>
            <Stepper
              activeStep={wizardStep}
              orientation={orientation}
              alternativeLabel={alternativeLabel}
              sx={{ mb: 3 }}
            >
              {WIZARD_STEPS.map((label) => (
                <Step key={label}>
                  <StepLabel>{label}</StepLabel>
                </Step>
              ))}
            </Stepper>

            {wizardStep === 0 && (
              <Stack spacing={2}>
                <FormControl fullWidth>
                  <InputLabel>PCF mode</InputLabel>
                  <Select
                    label="PCF mode"
                    value={pcfMode}
                    onChange={(e) => setPcfMode(String(e.target.value))}
                  >
                    {PCF_MODES.map((mode) => (
                      <MenuItem key={mode.value} value={mode.value}>
                        {mode.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
                <Typography variant="body2" color="text.secondary">
                  {PCF_MODES.find((m) => m.value === pcfMode)?.description}
                </Typography>
                <Typography variant="subtitle2">Products from your profile</Typography>
                {products.length === 0 ? (
                  <Alert severity="warning">
                    No products found. Add products under{' '}
                    <RouterLink to="/msme-profile">My company → Profile</RouterLink> first.
                  </Alert>
                ) : (
                  products.map((product, index) => (
                    <TextField
                      key={product.productId || product.productName}
                      label={product.productName}
                      value={product.productName}
                      InputProps={{ readOnly: true }}
                      helperText={`ID: ${product.productId || index + 1}`}
                    />
                  ))
                )}
              </Stack>
            )}

            {wizardStep === 1 && (
              <Stack spacing={2}>
                <TextField
                  label="Default functional unit"
                  value={functionalUnit}
                  onChange={(e) => setFunctionalUnit(e.target.value)}
                  helperText="ISO 14067 functional unit declaration (e.g. 1 kg fabric, 1 piece)"
                />
                <FormControl fullWidth>
                  <InputLabel>Allocation method</InputLabel>
                  <Select
                    label="Allocation method"
                    value={allocationMethod}
                    onChange={(e) => setAllocationMethod(String(e.target.value))}
                  >
                    {ALLOCATION_METHODS.map((method) => (
                      <MenuItem key={method.value} value={method.value}>
                        {method.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
                {products.map((product, index) => (
                  <Grid container spacing={2} key={product.productId || product.productName}>
                    <Grid item xs={12} md={4}>
                      <TextField
                        fullWidth
                        label={`${product.productName} — functional unit`}
                        value={product.functionalUnit || functionalUnit}
                        onChange={(e) => {
                          const next = [...products];
                          next[index] = { ...next[index], functionalUnit: e.target.value };
                          setProducts(next);
                        }}
                      />
                    </Grid>
                    <Grid item xs={12} md={4}>
                      <TextField
                        fullWidth
                        type="number"
                        label="Production volume"
                        value={product.productionVolume ?? ''}
                        onChange={(e) => {
                          const next = [...products];
                          next[index] = {
                            ...next[index],
                            productionVolume: Number(e.target.value) || 0,
                          };
                          setProducts(next);
                        }}
                      />
                    </Grid>
                    <Grid item xs={12} md={4}>
                      <TextField
                        fullWidth
                        label="Volume unit"
                        value={product.productionVolumeUnit || 'units'}
                        onChange={(e) => {
                          const next = [...products];
                          next[index] = { ...next[index], productionVolumeUnit: e.target.value };
                          setProducts(next);
                        }}
                      />
                    </Grid>
                  </Grid>
                ))}
              </Stack>
            )}

            {wizardStep === 2 && (
              <Stack spacing={2}>
                <Typography variant="body2" color="text.secondary">
                  Add keyword rules so shared costs auto-map to products (e.g. &quot;cotton yarn&quot; →
                  Product A). AI agents apply these before row-by-row classification.
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={5}>
                    <TextField
                      fullWidth
                      label="Keyword / vendor pattern"
                      value={rulePattern}
                      onChange={(e) => setRulePattern(e.target.value)}
                      placeholder="e.g. electricity, supplier name"
                    />
                  </Grid>
                  <Grid item xs={12} md={5}>
                    <FormControl fullWidth>
                      <InputLabel>Product</InputLabel>
                      <Select
                        label="Product"
                        value={ruleProductName}
                        onChange={(e) => setRuleProductName(String(e.target.value))}
                      >
                        {products.map((p) => (
                          <MenuItem key={p.productName} value={p.productName}>
                            {p.productName}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={2}>
                    <Button fullWidth variant="outlined" onClick={addRule} sx={{ height: '56px' }}>
                      Add rule
                    </Button>
                  </Grid>
                </Grid>
                {rules.map((rule) => (
                    <Chip key={String(rule.ruleId || rule.name)} label={String(rule.name || rule.pattern)} />
                  ))}
              </Stack>
            )}

            {wizardStep === 3 && (
              <Stack spacing={2}>
                <Typography variant="body2">
                  {pcfMode === 'quick'
                    ? 'Save your setup to publish workflow-based product estimates. Transaction AI classification is not used in Quick estimate mode.'
                    : pcfMode === 'detailed'
                      ? 'Save your setup, then run AI bulk classification with a stricter 85% confidence gate. Only Tier-1 attributed transactions feed the detailed LCI view.'
                      : 'Save your setup, then run AI bulk classification. Only low-confidence rows go to the exception queue in Operational mode.'}
                </Typography>
                <Stack direction="row" spacing={1} flexWrap="wrap">
                  <Button variant="outlined" onClick={() => handleSaveSetup(false)} disabled={saving}>
                    Save setup
                  </Button>
                  {supportsAutoClassify && (
                    <>
                      <Button
                        variant="outlined"
                        onClick={() => handleRunAiClassify(true)}
                        disabled={runningAi}
                      >
                        Preview AI classification
                      </Button>
                      <Button
                        variant="contained"
                        onClick={async () => {
                          await handleSaveSetup(false);
                          await handleRunAiClassify(false);
                          await handleSaveSetup(true);
                        }}
                        disabled={saving || runningAi}
                      >
                        Complete setup &amp; run AI
                      </Button>
                    </>
                  )}
                  {!supportsAutoClassify && (
                    <Button
                      variant="contained"
                      onClick={() => handleSaveSetup(true)}
                      disabled={saving}
                    >
                      Complete setup
                    </Button>
                  )}
                </Stack>
              </Stack>
            )}

            <Stack direction="row" justifyContent="space-between" sx={{ mt: 3 }}>
              <Button disabled={wizardStep === 0} onClick={() => setWizardStep((s) => s - 1)}>
                Back
              </Button>
              {wizardStep < WIZARD_STEPS.length - 1 ? (
                <Button variant="contained" onClick={() => setWizardStep((s) => s + 1)}>
                  Next
                </Button>
              ) : null}
            </Stack>
          </CardContent>
        </Card>
      )}

      <Card variant="outlined">
        <CardContent>
          <Stack direction="row" justifyContent="space-between" alignItems="center" mb={2}>
            <Typography variant="h6">Unified product PCF</Typography>
            <Stack direction="row" spacing={1}>
              <Button size="small" onClick={load}>
                Refresh
              </Button>
              {setupComplete && (
                <Button
                  size="small"
                  variant="outlined"
                  onClick={() => handleAnalyzeFeedOnly(false)}
                  disabled={runningAi}
                >
                  {runningAi ? 'Analyzing…' : 'Analyze feed only'}
                </Button>
              )}
              {setupComplete && supportsAutoClassify && (
                <Button
                  size="small"
                  variant="contained"
                  onClick={() => handleRunAiClassify(false)}
                  disabled={runningAi}
                >
                  {runningAi ? MODULE_CHECK_LABELS.pcf.running : MODULE_CHECK_LABELS.pcf.button}
                </Button>
              )}
            </Stack>
          </Stack>
          <OrchestrationRunPanel
            lastRun={lastPcfRun}
            stages={pcfStages}
            title={MODULE_CHECK_LABELS.pcf.panelTitle}
            running={runningAi}
            runningStageLabel={MODULE_CHECK_LABELS.pcf.running}
            showEmptyPrompt={setupComplete}
          />
          <Typography variant="body2" color="text.secondary" mb={2}>
            {pcfMode === 'quick'
              ? 'Workflow-based kg CO₂e per product from the Manufacturing Workflow Planner.'
              : pcfMode === 'detailed'
                ? 'Tier-1 attributed transaction emissions per product — workflow estimates are excluded.'
                : `${MODULE_CHECK_LABELS.pcf.subtitle} Combines manufacturing workflow LCI with transaction allocation for one view per product.`}
          </Typography>
          {unifiedProducts.length === 0 ? (
            <Alert severity="warning">No product footprints calculated yet. Complete setup above.</Alert>
          ) : (
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Product</TableCell>
                  {showWorkflowColumn && <TableCell align="right">Workflow kg CO₂e</TableCell>}
                  {showTransactionColumn && <TableCell align="right">Transaction kg CO₂e</TableCell>}
                  <TableCell align="right">
                    {pcfMode === 'quick' ? 'Workflow total' : pcfMode === 'detailed' ? 'Tier-1 total' : 'Combined kg CO₂e'}
                  </TableCell>
                  <TableCell align="right">Per functional unit</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {unifiedProducts.map((product) => (
                  <TableRow key={product.productName}>
                    <TableCell>{product.productName}</TableCell>
                    {showWorkflowColumn && (
                      <TableCell align="right">{product.workflowKgCo2e?.toFixed(2) ?? '—'}</TableCell>
                    )}
                    {showTransactionColumn && (
                      <TableCell align="right">{product.transactionKgCo2e?.toFixed(2) ?? '—'}</TableCell>
                    )}
                    <TableCell align="right">{product.combinedKgCo2e?.toFixed(2) ?? '—'}</TableCell>
                    <TableCell align="right">
                      {product.kgCo2ePerFunctionalUnit?.toFixed(4) ?? '—'}
                      {product.productionVolume ? ` / ${product.functionalUnit}` : ''}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
          <Button
            component={RouterLink}
            to={reportingTabHref('iso14067')}
            variant="outlined"
            sx={{ mt: 2 }}
          >
            Open ISO 14067 disclosure report
          </Button>
        </CardContent>
      </Card>

      {exceptions.length > 0 && (
        <Card variant="outlined">
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Exception queue ({exceptions.length})
            </Typography>
            <Typography variant="body2" color="text.secondary" mb={2}>
              Low-confidence or unclassified transactions — review in Operational data.
            </Typography>
            <Button component={RouterLink} to={DOCUMENT_UPLOAD_PATH} variant="contained" size="small">
              Review in Operational data
            </Button>
          </CardContent>
        </Card>
      )}
    </Stack>
  );
};

export default ProductPcfWorkspace;
